-- Source geometry remains immutable; activation is a selection, not a manual review.
DROP TRIGGER admin_dataset_update_guard;
CREATE TRIGGER admin_dataset_update_guard BEFORE UPDATE ON admin_boundary_dataset BEGIN
 SELECT CASE WHEN NEW.id IS NOT OLD.id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.provider IS NOT OLD.provider OR NEW.code_namespace IS NOT OLD.code_namespace OR NEW.release_version IS NOT OLD.release_version OR NEW.released_at IS NOT OLD.released_at OR NEW.acquired_at IS NOT OLD.acquired_at OR NEW.source_reference IS NOT OLD.source_reference OR NEW.source_checksum IS NOT OLD.source_checksum OR NEW.metadata_json IS NOT OLD.metadata_json OR NEW.coverage_json IS NOT OLD.coverage_json OR NEW.manifest_sha256 IS NOT OLD.manifest_sha256 OR NEW.expected_features IS NOT OLD.expected_features OR NEW.expected_chunks IS NOT OLD.expected_chunks OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR NEW.version<>OLD.version+1 OR NOT((OLD.status='draft' AND NEW.status IN('draft','active')) OR (OLD.status='active' AND NEW.status='retired') OR(OLD.status='retired' AND NEW.status='active')) THEN RAISE(ABORT,'ADMIN_RELEASE_IMMUTABLE') END;
 SELECT CASE WHEN OLD.status<>'draft' AND (NEW.license_reference IS NOT OLD.license_reference OR NEW.license_note IS NOT OLD.license_note OR NEW.attribution IS NOT OLD.attribution OR NEW.reviewed_by IS NOT OLD.reviewed_by OR NEW.reviewed_at IS NOT OLD.reviewed_at) THEN RAISE(ABORT,'ADMIN_REVIEW_IMMUTABLE') END;
 SELECT CASE WHEN NEW.status='active' AND ((SELECT COUNT(*) FROM admin_boundary_chunk WHERE organization_id=NEW.organization_id AND dataset_id=NEW.id)<>NEW.expected_chunks OR (SELECT COALESCE(SUM(feature_count),0) FROM admin_boundary_chunk WHERE organization_id=NEW.organization_id AND dataset_id=NEW.id)<>NEW.expected_features OR (SELECT COUNT(*) FROM admin_boundary WHERE organization_id=NEW.organization_id AND dataset_id=NEW.id)<>NEW.expected_features) THEN RAISE(ABORT,'ADMIN_RELEASE_INCOMPLETE') END;
END;
